11	use Application\API\Parameters\Handlers\BaseRuleHandler;
12	use Application\Countries\API\AppCountriesAPIInterface;
13	use Application_Countries_Country;
14	
15	/**
16	 * Bridges the {@see AppCountriesParamRule} into the container's handler
17	 * architecture.
18	 *
19	 * Provides type-narrowed overrides for {@see resolveValue()} (returning
20	 * `Application_Countries_Country[]`) and {@see getRule()} (returning
21	 * `?AppCountriesParamRule`) so consumers receive correctly-typed values
22	 * without casting.
23	 *
24	 * Mirrors {@see AppCountryRuleHandler} (singular) for pattern consistency.
25	 *
26	 * @package Countries
27	 * @subpackage API
28	 *
29	 * @method AppCountriesAPIInterface getMethod()
30	 */
31	class AppCountriesRuleHandler extends BaseRuleHandler
32	{
33	    public function __construct(AppCountriesAPIInterface $method)
34	    {
35	        parent::__construct($method);
36	    }
37	
38	    /**
39	     * Returns the resolved list of countries, or an empty array if none
40	     * could be resolved.
41	     *
42	     * @return Application_Countries_Country[]
43	     */
44	    public function resolveValue(): array
45	    {
46	        $value = parent::resolveValue();
47	
48	        if(is_array($value)) {
49	            return $value;
50	        }
51	
52	        return array();
53	    }
54	
55	    /**
56	     * Resolves the list of countries from the underlying OrRule's valid
57	     * parameter set, or an empty array if no set matched.
58	     *
59	     * @return Application_Countries_Country[]
60	     */
61	    protected function resolveValueFromSubject(): array
62	    {
63	        return $this->getRule()?->getCountries() ?? array();
64	    }
65	
66	    /**
67	     * Returns the underlying {@see AppCountriesParamRule}, or `null` if
68	     * the rule has not been registered yet.
69	     *
70	     * @return AppCountriesParamRule|null
71	     */
72	    public function getRule(): ?AppCountriesParamRule
73	    {
74	        $rule = parent::getRule();
75	
76	        if($rule instanceof AppCountriesParamRule) {
77	            return $rule;
78	        }
79	
80	        return null;
81	    }
82	
83	    protected function createRule(): AppCountriesParamRule
84	    {
85	        return new AppCountriesParamRule($this->getMethod());
86	    }
87	}

